#++++++++++++++++   SolutionFileSettings   ++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
#++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
definitions.append(StructureDefinition(
    className='SolutionFileSettings',
    writeFile='SimulationSettings.h',
    addDictionaryAccess=False,
    appendToFile=True,
    classDescription=r'The coordinates solution file: all coordinates of the system versus time, read by the SolutionViewer and exudyn.utilities.LoadSolutionFile.',
    typicalPaths='simulationSettings.solution',
    writePybindIncludes=True,
    members=[
        StructureParameter(type='SolutionFileExportSettings', 
            pythonName='export', cplusplusName='exportSettings',
            defaultValue=NoDefaultValue,
            description=r'which quantities are written in addition to the coordinates'),
        StructureParameter(type=Tbool,
            pythonName='write',
            defaultValue=True,
            description=r"""flag (true/false), which determines if the coordinates are written to the solution file; standard quantities that are written are: solution is written as displacements and coordinatesODE1; for additional quantities, see export"""),
        StructureParameter(type=TFileName,
            pythonName='name',
            defaultValue='solution/coordinatesSolution',
            description=r"""filename and (relative) path of the solution file containing all multibody system coordinates versus time; the default is in the directory solution/, like every file a run writes by default, so that nothing is written beside the script; directory will be created if it does not exist; character encoding of string is up to your filesystem, but for compatibility, it is recommended to use letters, numbers and '_' only; filename ending will be added automatically if not provided: .txt in case of text mode and .sol in case of binary solution files (binary=True)"""),
        StructureParameter(type=TReal(minimum=0),
            pythonName='writePeriod',
            defaultValue=0.01,
            description=r"""time span (period), determines how often the solution file is written during a simulation"""),
        StructureParameter(type=Tbool,
            pythonName='append',
            defaultValue=False,
            description=r"""flag (true/false); if true, the solution and the solver information are appended to existing files (otherwise created); in BINARY mode, files are always replaced and this parameter is ineffective!"""),
        StructureParameter(type=Tbool,
            pythonName='binary',
            defaultValue=False,
            description=r"""if true, the solution file is written in binary format for improved speed and smaller file sizes; setting solution.precision >= 8 uses double (8 bytes), otherwise float (4 bytes) is used; note that append is ineffective and files are always replaced without asking! If not provided, file ending will read .sol in case of binary files and .txt in case of text files"""),
        StructureParameter(type=Tbool,
            pythonName='writeHeader',
            defaultValue=True,
            description=r"""flag (true/false); if true, file header is written (turn off, e.g. for multiple runs of time integration)"""),
        StructureParameter(type=Tbool,
            pythonName='writeFooter',
            defaultValue=True,
            description=r"""flag (true/false); if true, information at end of simulation is written: convergence, total solution time, statistics"""),
        StructureParameter(type=Tbool,
            pythonName='writeInitialValues',
            defaultValue=True,
            description=r"""flag (true/false); if true, initial values are exported for the start time; applies to the solution file and the sensor files; this may not be wanted in the append file mode if the initial values are identical to the final values of a previous computation"""),
        StructureParameter(type=TString,
            pythonName='information',
            defaultValue=NoDefaultValue,
            description=r"""special information added to header of solution file (e.g. parameters and settings, modes, ...); character encoding my be UTF-8, restricted to characters in [](#sec-utf8), but for compatibility, it is recommended to use ASCII characters only (95 characters, see wiki)"""),
        StructureParameter(type=TIndex(greaterThan=0),
            pythonName='flushAboveCoordinates',
            defaultValue=10000,
            description=r"""number of coordinates above which the buffers of the solution file are always flushed, irrespectively of solution.flushFilesImmediately; for larger files, writing takes so much time that flushing does not add considerable time"""),
        ],
    ))

