#++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
#++++++++++++++++   NumericalDifferentiationSettings   ++++++++++++++++++++++++++++++++++++++++++++
#++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
definitions.append(StructureDefinition(
    className='NumericalDifferentiationSettings',
    writeFile='SimulationSettings.h',
    addDictionaryAccess=False,
    appendToFile=True,
    classDescription=r'Settings for numerical differentiation of a function (needed for computation of numerical jacobian e.g. in implizit integration).',
    typicalPaths='simulationSettings.timeIntegration.newton,simulationSettings.staticSolver.newton',
    writePybindIncludes=True,
    members=[
        StructureParameter(type=Tbool,
            pythonName='addReferenceCoordinatesToEpsilon',
            defaultValue=False,
            description=r"""True: for the size estimation of the differentiation parameter, the reference coordinate $q^{Ref}_i$ is added to ABRV:ODE2 coordinates --> see; False: only the current coordinate is used for size estimation of the differentiation parameter"""),
        StructureParameter(type=Tbool,
            pythonName='doSystemWideDifferentiation',
            defaultValue=False,
            description=r"""True: system wide differentiation (e.g. all ABRV:ODE2 equations w.r.t. all ABRV:ODE2 coordinates); False: only local (object) differentiation"""),
        StructureParameter(type=Tbool,
            pythonName='forAE',
            defaultValue=False,
            description=r"flag (true/false); false = perform direct computation of jacobian for algebraic equations (AE), true = use numerical differentiation; as there must always exist an analytical implemented jacobian for AE, 'true' should only be used for verification"),
        StructureParameter(type=Tbool,
            pythonName='forODE2',
            defaultValue=False,
            description=r'flag (true/false); false = perform direct computation (e.g., using autodiff) of jacobian for ODE2 equations, true = use numerical differentiation; numerical differentiation is less efficient and may lead to numerical problems, but may smoothen problems of analytical derivatives; sometimes the analytical derivative may neglect terms'),
        StructureParameter(type=Tbool,
            pythonName='forODE2Connectors',
            defaultValue=False,
            description=r'flag (true/false); false: if also forODE2==false, perform direct computation of jacobian for ODE2 terms for connectors; else: use numerical differentiation; NOTE: THIS FLAG IS FOR DEVELOPMENT AND WILL BE ERASED IN FUTURE'),
        StructureParameter(type=TReal(minimum=0),
            pythonName='minimumCoordinateSize',
            defaultValue=0.01,
            description=r'minimum size of coordinates in relative differentiation parameter'),
        StructureParameter(type=TReal(minimum=0),
            pythonName='relativeEpsilon',
            defaultValue=1e-7,
            description=r"""relative differentiation parameter epsilon; the numerical differentiation parameter $\varepsilon$ follows from the formula ($\varepsilon = \varepsilon_\mathrm{relative}*max(q_{min}, |q_i + [q^{Ref}_i]|)$, with $\varepsilon_\mathrm{relative}$=relativeEpsilon, $q_{min} = $minimumCoordinateSize, $q_i$ is the current coordinate which is differentiated, and $qRef_i$ is the reference coordinate of the current coordinate"""),
        StructureParameter(type=Tbool,
            pythonName='jacobianConnectorDerivative',
            defaultValue=True,
            description=r'True: for analytic Jacobians of connectors, the Jacobian derivative is computed, causing additional CPU costs and not beeing available for all connectors or markers (thus switching to numerical differentiation); False: Jacobian derivative is neglected in analytic Jacobians (but included in numerical Jacobians), which often has only minor influence on convergence'),
        StructureParameter(type=Tbool, cFlags=SFDeprecated,
            pythonName='forODE2connectors',
            deprecated=Deprecated('1.12.256', 2031),
            defaultValue=NoDefaultValue,
            description=r'forODE2Connectors'),
        ],
    ))

